    """
    result = {}
    for k, v in constant_data.items():
        if isinstance(v, CooTensor):
            new_m = lin_op_shape[0] if len(lin_op_shape) > 0 else 1
            new_n = lin_op_shape[1] if len(lin_op_shape) > 1 else 1
